@startuml

enum BuildingMaterial {
  wood
  brick
  concrete
}

class House {
  + Address : string
  + BuildingMaterial : BuildingMaterial
}

abstract class Basement {
  + Size : double
  + Name : string
}

class EarthBasement extends Basement {
  + Humidity : double
}

class ConcreteBasement extends Basement {}

class SemiDetachedHouse extends House {
  + Garden : boolean
  + Windows : int
}

class Carport {
  + DoublePort : boolean
  + FlatRoof : boolean
}

class Garage {
  + AutomaticGarageDoor : boolean
}

class Company {
  + Name : string
  + Address : string
}

class JobLog {
  + Hours : int
  + Price : double
}

House "1" *-- "0..1" Basement
House "1" -- "*" Company
House "1" -- "*" JobLog
Company "1" -- "*" JobLog
SemiDetachedHouse "1" -- "2" Carport
SemiDetachedHouse "1" -- "1" Garage

@enduml

